/** Events */
export const events = {
	operationProgress: makeEvent<OperationProgress>("operation-progress"),
	repositoryChanged: makeEvent<RepositoryChanged>("repository-changed"),
	updateProgress: makeEvent<UpdateProgress>("update-progress"),
};

/* Types */
/**  A signed-in user. */
export type Account = {
	login: string,
	avatarUrl: string,
	htmlUrl: string,
};

/**  The connected accounts, in the order they were added. */
export type Accounts = {
	accounts: Account[],
	/**
	 *  Login of the account that works where nothing names another: one of
	 *  `accounts`, as long as there is any.
	 */
	active: string | null,
	/**
	 *  Logins of the accounts whose token GitHub no longer accepts: revoked,
	 *  expired, or the authorisation of the application withdrawn. Never stored:
	 *  the application fills it in as GitHub answers.
	 */
	refused: string[],
};

/**  A model the user can pick. */
export type AiModel = {
	/**  What the API calls it, such as `claude-opus-5-5`. */
	id: string,
	/**  What people call it; the id again when the provider gives no name. */
	name: string,
};

/**  What the frontend receives when a command fails. */
export type AppError = 
/**  The repository was never opened, or was closed. */
{ kind: "repositoryNotOpen"; message: string } | 
/**  libgit2, the `git` binary or the core layer refused the operation. */
{ kind: "git"; message: string } | 
/**  The user stopped the operation: nothing went wrong. */
{ kind: "cancelled"; message: string } | 
/**  The operating system refused something (opening a file, for instance). */
{ kind: "system"; message: string } | 
/**  GitHub, the keychain or the sign-in refused something. */
{ kind: "gitHub"; message: string } | 
/**
 *  GitHub no longer accepts the token of an account, which the message names:
 *  it has to be connected again.
 */
{ kind: "tokenRefused"; message: string } | 
/**  The model provider, or the keychain holding its key, refused something. */
{ kind: "ai"; message: string } | 
/**  The update of the application could not be found, checked or installed. */
{ kind: "update"; message: string };

/**  What changed: the history (refs, `HEAD`, index) or only the working tree. */
export type ChangeKind = "history" | "workingTree";

/**  Where a workflow run, a job or a step stands. */
export type CheckState = 
/**  Not started: no runner took it yet, or the steps before it are not done. */
"queued" | 
/**  Held until someone approves it. */
"waiting" | "inProgress" | "success" | "failure" | "cancelled" | "skipped" | 
/**  Finished without a verdict, or in a state this version does not know. */
"neutral";

export type Comment = {
	id: number,
	author: string,
	body: string,
	htmlUrl: string,
	createdAt: number,
};

export type CommitDetails = {
	id: string,
	summary: string,
	/**  The message without its summary line. */
	body: string,
	author: Signature,
	committer: Signature,
	parents: string[],
	files: FileChange[],
};

/**  The message a model proposes, ready for the two fields of the commit form. */
export type CommitSuggestion = {
	summary: string,
	/**  Empty when the summary says it all. */
	body: string,
	/**
	 *  Files whose diff was shortened or left out before asking; never
	 *  silently, the user is told.
	 */
	shortenedFiles: number,
};

/**
 *  Which version of a conflicted file to keep whole.
 * 
 *  Git's naming: during a merge `Ours` is the checked-out branch and `Theirs`
 *  the branch being merged; during a rebase the two are swapped.
 */
export type ConflictSide = "ours" | "theirs";

/**  What GitHub hands out at the start of the flow. */
export type DeviceCode = {
	/**  Opaque, sent back when polling. */
	deviceCode: string,
	/**  What the user types on the verification page. */
	userCode: string,
	verificationUri: string,
	/**  Seconds to wait between two polls. */
	interval: number,
	/**  Seconds before the codes expire. */
	expiresIn: number,
};

/**
 *  One step of the device sign-in, as the UI sees it (the token itself never
 *  leaves the backend).
 */
export type DeviceStatus = { kind: "pending" } | { kind: "slowDown" } | { kind: "signedIn"; value: Account } | { kind: "failed"; value: string };

export type DiffLine = {
	kind: DiffLineKind,
	oldLineno: number | null,
	newLineno: number | null,
	/**  The line without its terminator. */
	content: string,
};

export type DiffLineKind = "context" | "addition" | "deletion" | 
/**  Git's "\ No newline at end of file" marker. */
"noNewline";

/**  A file touched by a commit, compared to the commit's first parent. */
export type FileChange = {
	path: string,
	/**  Previous path, for renames and copies. */
	oldPath: string | null,
	status: FileStatus,
	additions: number,
	deletions: number,
	binary: boolean,
};

export type FileContents = {
	/**  Content before the change; `None` for an added file. */
	old: string | null,
	/**  Content after the change; `None` for a deleted file. */
	new: string | null,
	/**  Either side looks binary; the texts are then empty. */
	binary: boolean,
	/**  Either side exceeds the size limit; the texts are then empty. */
	tooLarge: boolean,
};

/**  The changes made to one file. */
export type FileDiff = {
	path: string,
	oldPath: string | null,
	status: FileStatus,
	binary: boolean,
	hunks: Hunk[],
};

export type FileStatus = "added" | "deleted" | "modified" | "renamed" | "copied" | "typeChanged" | 
/**  Unresolved merge conflict (working tree only). */
"conflicted";

/**  Where a repository lives on GitHub, and the connected account that works on it. */
export type GitHubLink = {
	repo: GitHubRepo,
	/**  Login of the account used for this repository; `None` when none is connected. */
	account: string | null,
	/**
	 *  Login of the account the repository names, when it is a connected one.
	 *  Without it the account is one that GitHub lets push to the repository,
	 *  the active one first (see [`Accounts::for_repository`]).
	 */
	bound: string | null,
};

/**  A repository on github.com, as `owner/name`. */
export type GitHubRepo = {
	owner: string,
	name: string,
};

/**  One row of the commit graph, ready to be drawn. */
export type GraphRow = {
	id: string,
	summary: string,
	authorName: string,
	authorEmail: string,
	/**  Author time, in seconds since the Unix epoch. */
	time: number,
	layout: RowLayout,
};

/**  What `HEAD` points at. */
export type HeadInfo = {
	/**  The checked-out branch; `None` when `HEAD` is detached. */
	branch: string | null,
	/**  The checked-out commit; `None` in a repository without commits. */
	target: string | null,
	/**  The remote-tracking branch `branch` follows, such as `origin/main`. */
	upstream: string | null,
	/**  Commits on `branch` that `upstream` lacks. */
	ahead: number,
	/**  Commits on `upstream` that `branch` lacks. */
	behind: number,
};

export type Hunk = {
	/**  The `@@ -1,3 +1,4 @@` line. */
	header: string,
	lines: DiffLine[],
};

/**  Who commits are attributed to, from `user.name` and `user.email`. */
export type Identity = {
	name: string,
	email: string,
};

export type Issue = {
	number: number,
	title: string,
	body: string,
	state: ItemState,
	author: string,
	labels: Label[],
	comments: number,
	htmlUrl: string,
	createdAt: number,
	updatedAt: number,
};

export type ItemState = "open" | "closed";

export type Label = {
	name: string,
	/**  Six hex digits, as GitHub stores it. */
	color: string,
};

/**  A lane (column) of the graph where it crosses the edge of a row. */
export type LaneRef = {
	lane: number,
	color: number,
};

/**  One line of git's progress output, such as `Receiving objects:  45% (123/273)`. */
export type OperationProgress = {
	/**  The repository path (or the clone destination) the operation runs on. */
	path: string,
	/**  `fetch`, `pull`, `push` or `clone`. */
	operation: string,
	message: string,
	/**  Parsed from the line when it carries a percentage. */
	percent: number | null,
};

export type Provider = 
/**  Anthropic's API, with a key. */
"anthropic" | 
/**  OpenAI's API, with a key. */
"openai" | 
/**  The `claude` program installed on the machine, with its own sign-in. */
"claudecode" | 
/**  The `codex` program installed on the machine, with its own sign-in. */
"codex";

export type PullRequest = {
	number: number,
	title: string,
	body: string,
	state: ItemState,
	draft: boolean,
	merged: boolean,
	author: string,
	/**  Branch the changes come from. */
	head: string,
	/**  Branch the changes go into. */
	base: string,
	htmlUrl: string,
	/**  Seconds since the Unix epoch. */
	createdAt: number,
	updatedAt: number,
};

/**  A branch or tag and the commit it points at. */
export type RefInfo = {
	/**  Short name, such as `main`, `origin/main` or `v1.0`. */
	name: string,
	kind: RefKind,
	/**  Id of the commit the ref resolves to. */
	target: string,
};

export type RefKind = "localBranch" | "remoteBranch" | "tag";

/**  A repository the account can reach, as offered for cloning. */
export type RemoteRepository = {
	/**  `owner/name`. */
	fullName: string,
	description: string,
	private: boolean,
	fork: boolean,
	archived: boolean,
	/**  The HTTPS address to clone from. */
	cloneUrl: string,
	/**  Seconds since the Unix epoch; 0 for a repository nothing was pushed to. */
	pushedAt: number,
};

export type RepoInfo = {
	name: string,
	/**  The working directory, or the git directory of a bare repository. */
	path: string,
	head: HeadInfo,
	/**  Whether a merge, rebase, cherry-pick or revert is waiting to be finished. */
	state: RepoState,
	/**  `None` when `user.name` or `user.email` is not configured. */
	author: Identity | null,
	remotes: string[],
};

/**  Whether an operation is waiting for the user to resolve conflicts or continue. */
export type RepoState = "clean" | "merge" | "rebase" | "cherryPick" | "revert" | "bisect" | "other";

/**  Emitted at most every few hundred milliseconds per repository. */
export type RepositoryChanged = {
	/**  The repository path, as `RepoInfo::path` reports it. */
	path: string,
	kind: ChangeKind,
};

/**  Where a commit sits in the graph and which lines cross its row. */
export type RowLayout = {
	lane: number,
	color: number,
	/**  Lanes coming from the row above that end at this commit. */
	incoming: LaneRef[],
	/**  Lanes leaving this commit towards its parents in the rows below. */
	outgoing: LaneRef[],
	/**  Lanes that cross the row without touching this commit. */
	passing: LaneRef[],
};

export type Signature = {
	name: string,
	email: string,
	/**  Seconds since the Unix epoch. */
	time: number,
};

/**  A saved stash, newest first (`index` 0 is `stash@{0}`). */
export type StashEntry = {
	index: number,
	message: string,
	id: string,
};

/**  A file that differs between two of `HEAD`, the index and the working tree. */
export type StatusEntry = {
	path: string,
	/**  Previous path, for renames. */
	oldPath: string | null,
	status: FileStatus,
};

/**  How much of the update is downloaded; the installation follows. */
export type UpdateProgress = {
	/**  `None` when the server did not say how large the download is. */
	percent: number | null,
};

/**  One job of a run, with the steps it goes through. */
export type WorkflowJob = {
	id: number,
	name: string,
	state: CheckState,
	htmlUrl: string,
	/**  Seconds since the Unix epoch; `None` until a runner starts it. */
	startedAt: number | null,
	completedAt: number | null,
	steps: WorkflowStep[],
};

/**  One execution of a workflow. */
export type WorkflowRun = {
	id: number,
	/**  The workflow, as its file names it (`CI`). */
	workflow: string,
	/**  What the run is about: the commit summary, or the title of the pull request. */
	title: string,
	/**  Counts the runs of this workflow. */
	number: number,
	/**  More than 1 once the run was started again. */
	attempt: number,
	/**  What started it: `push`, `pull_request`, `schedule`… */
	event: string,
	/**  Empty when the run is not tied to a branch. */
	branch: string,
	/**  The commit the workflow runs on. */
	commit: string,
	state: CheckState,
	actor: string,
	htmlUrl: string,
	/**  Seconds since the Unix epoch, for this attempt. */
	startedAt: number,
	/**  When it last changed: once finished, when it ended. */
	updatedAt: number,
};

export type WorkflowStep = {
	/**  Its place in the job, from 1. */
	number: number,
	name: string,
	state: CheckState,
	startedAt: number | null,
	completedAt: number | null,
};

export type WorkingTreeStatus = {
	/**  Index compared to `HEAD`: what the next commit will contain. */
	staged: StatusEntry[],
	/**  Working tree compared to the index, untracked files included. */
	unstaged: StatusEntry[],
	/**  Paths with unresolved merge conflicts. */
	conflicted: string[],
};

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

function makeEvent<T>(name: string, serialize?: (payload: T) => unknown, deserialize?: (payload: any) => T) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<T>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: T) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: T) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => target.once(name, mapEvent(cb)),
        emit: ((payload: T) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    });

    return Object.assign(fn, base);
}

